import{_ as e,o as a,c as r,ag as l}from"./chunks/framework.DTisvaUJ.js";const p=JSON.parse('{"title":"Azure Translatorの導入","description":"Mutelinkでクラウド翻訳を使うためのAzure Translatorの導入手順。リソースの作成、無料枠、キーとリージョンの設定を案内します。","frontmatter":{"description":"Mutelinkでクラウド翻訳を使うためのAzure Translatorの導入手順。リソースの作成、無料枠、キーとリージョンの設定を案内します。","head":[["meta",{"name":"robots","content":"index, follow, max-image-preview:large"}],["link",{"rel":"canonical","href":"https://utyujinn.github.io/Mutelink-releases/guide/azure-translator"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Mutelink"}],["meta",{"property":"og:locale","content":"ja_JP"}],["meta",{"property":"og:title","content":"Azure Translatorの導入 | Mutelink"}],["meta",{"property":"og:description","content":"Mutelinkでクラウド翻訳を使うためのAzure Translatorの導入手順。リソースの作成、無料枠、キーとリージョンの設定を案内します。"}],["meta",{"property":"og:url","content":"https://utyujinn.github.io/Mutelink-releases/guide/azure-translator"}],["meta",{"property":"og:image","content":"https://utyujinn.github.io/Mutelink-releases/images/og-image.png"}],["meta",{"property":"og:image:width","content":"1920"}],["meta",{"property":"og:image:height","content":"1080"}],["meta",{"property":"og:image:alt","content":"Mutelink"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Azure Translatorの導入 | Mutelink"}],["meta",{"name":"twitter:description","content":"Mutelinkでクラウド翻訳を使うためのAzure Translatorの導入手順。リソースの作成、無料枠、キーとリージョンの設定を案内します。"}],["meta",{"name":"twitter:image","content":"https://utyujinn.github.io/Mutelink-releases/images/og-image.png"}],["meta",{"name":"twitter:image:alt","content":"Mutelink"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://utyujinn.github.io/Mutelink-releases/guide/azure-translator"}],["link",{"rel":"alternate","hreflang":"en","href":"https://utyujinn.github.io/Mutelink-releases/en/guide/azure-translator"}],["link",{"rel":"alternate","hreflang":"zh-Hans","href":"https://utyujinn.github.io/Mutelink-releases/zh/guide/azure-translator"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://utyujinn.github.io/Mutelink-releases/ko/guide/azure-translator"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://utyujinn.github.io/Mutelink-releases/guide/azure-translator"}]]},"headers":[],"relativePath":"guide/azure-translator.md","filePath":"guide/azure-translator.md"}'),o={name:"guide/azure-translator.md"};function n(i,t,s,u,d,c){return a(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="azure-translatorの導入" tabindex="-1">Azure Translatorの導入 <a class="header-anchor" href="#azure-translatorの導入" aria-label="Permalink to &quot;Azure Translatorの導入&quot;">​</a></h1><p>MutelinkでAzure Translator(Microsoftのクラウド翻訳)を使うための、キーの作り方です。月200万文字までは無料の枠(F0)で使えます。</p><p>このPCの中で動く翻訳(PLaMo、TranslateGemma)なら、この準備は要りません。どれを使うかは、<a href="/Mutelink-releases/compare/translation">翻訳エンジンの比較</a>を見て決めてください。</p><div class="info custom-block"><p class="custom-block-title">先に知っておくこと</p><ul><li>Azureの登録には、住所、電話番号、クレジットカードによる本人確認が必要です。この手順では、登録・認証を済ませた<strong>従量課金制のサブスクリプション</strong>を用意します。Microsoftアカウントにサインアップしただけでは、準備は終わりません。</li><li>無料の枠(F0)を選んでいる限り、月200万文字を超えても料金はかかりません(その月は翻訳できなくなります)。</li><li>翻訳する文は、Microsoftのサーバーに送られます(<a href="/Mutelink-releases/about/privacy">プライバシー</a>)。</li><li>Azureポータルの画面や言葉は、変わることがあります。下の手順と違うときは、近い名前の項目を探してください。</li></ul></div><h2 id="_1-azureの従量課金制サブスクリプションを用意する" tabindex="-1">1. Azureの従量課金制サブスクリプションを用意する <a class="header-anchor" href="#_1-azureの従量課金制サブスクリプションを用意する" aria-label="Permalink to &quot;1. Azureの従量課金制サブスクリプションを用意する&quot;">​</a></h2><ol><li><a href="https://azure.microsoft.com/ja-jp/pricing/purchase-options/azure-account" target="_blank" rel="noreferrer">Azureアカウントの登録ページ</a>を開き、従量課金制の登録を始めます。</li><li>Microsoftアカウントでサインインします(無ければ、その場で作れます)。</li><li>案内に従って、住所などの登録情報を入力し、電話番号とクレジットカードによる認証、支払い方法の登録を済ませます。</li><li><a href="https://portal.azure.com/" target="_blank" rel="noreferrer">Azureポータル</a>の「サブスクリプション」で、従量課金制のサブスクリプションが作られ、状態が有効になっていることを確認します。</li><li>無料アカウントから始めた場合は、必要に応じて「アップグレード」から従量課金制への移行を済ませます。</li></ol><p>すでに有効な従量課金制サブスクリプションがあるときは、この手順は要りません。</p><p>Azureの「従量課金制」と、Translatorリソースの「価格レベル」は別の設定です。次の手順では、Translatorの価格レベルを<strong>Free F0</strong>にします。ほかの有料サービスを作ったり、Translatorで有料の価格レベルを選んだりすると、その利用分には料金がかかります。</p><h2 id="_2-translatorのリソースを作る" tabindex="-1">2. Translatorのリソースを作る <a class="header-anchor" href="#_2-translatorのリソースを作る" aria-label="Permalink to &quot;2. Translatorのリソースを作る&quot;">​</a></h2><ol><li><a href="https://portal.azure.com/" target="_blank" rel="noreferrer">Azureポータル</a>を開きます。</li><li>上の検索欄に「Translator」と入れて、「Translator」(日本語表示では「翻訳ツール」)を選び、「作成」を押します。</li><li>次のように入れます。</li></ol><table tabindex="0"><thead><tr><th>項目</th><th>入れるもの</th></tr></thead><tbody><tr><td>サブスクリプション</td><td>自分のサブスクリプション(1つしか無ければ、そのまま)</td></tr><tr><td>リソース グループ</td><td>「新規作成」を押して、好きな名前(例: <code>mutelink</code>)</td></tr><tr><td>リージョン</td><td>近い場所(例: <code>Japan East</code>)。<strong>ここで選んだものを、あとでMutelinkに入れます</strong></td></tr><tr><td>名前</td><td>リソースを識別する名前(例: <code>mutelink-translator-1234</code>)。すでに使われていると表示されたら、末尾の数字などを変えます</td></tr><tr><td>価格レベル</td><td><strong>Free F0</strong>(月200万文字まで無料)</td></tr></tbody></table><ol start="4"><li>「確認と作成」を押して、内容を確かめてから「作成」を押します。</li><li>「デプロイが完了しました」と出たら、「リソースに移動」を押します。</li></ol><p>「リソースに移動」で、Translatorではなくリソース グループの画面が開くことがあります。その場合は、一覧から作成したTranslatorを選びます。作成直後は一覧にまだ出ていないこともあるので、画面の「最新の情報に更新」(リフレッシュ)を押し、表示されたTranslatorの名前をクリックしてください。</p><div class="tip custom-block"><p class="custom-block-title">「Free F0」が選べないとき</p><p>無料の枠は、1つのサブスクリプションに1つだけ作れます。以前に作ったTranslatorのリソースが残っていないか、確認してください。</p></div><h2 id="_3-キーとリージョンを確認する" tabindex="-1">3. キーとリージョンを確認する <a class="header-anchor" href="#_3-キーとリージョンを確認する" aria-label="Permalink to &quot;3. キーとリージョンを確認する&quot;">​</a></h2><ol><li>作ったTranslatorの画面を開き、左のメニューから「キーとエンドポイント」を開きます。リソース グループの画面にいる場合は、先に一覧のTranslatorをクリックします。</li><li>「キー 1」(KEY 1)をコピーします。</li><li>「場所/地域」(Location/Region)に出ている文字(例: <code>japaneast</code>)を控えます。</li></ol><div class="warning custom-block"><p class="custom-block-title">キーは人に見せないでください</p><p>キーを知っている人は、あなたの枠で翻訳できます。配信や画面共有、スクリーンショットに映さないようにしてください。漏れたときは、同じ画面の「キー 1 の再生成」で作り直せます。</p></div><h2 id="_4-mutelinkに入れる" tabindex="-1">4. Mutelinkに入れる <a class="header-anchor" href="#_4-mutelinkに入れる" aria-label="Permalink to &quot;4. Mutelinkに入れる&quot;">​</a></h2><ol><li>Mutelinkの 設定 &gt; 翻訳 を開きます。</li><li>「Azure Translator」の欄で、「Azure Translatorのキー」にキー 1を、「リージョン」に控えた文字(例: <code>japaneast</code>)を入れます。</li><li>翻訳のテストで、訳が返ることを確認します。</li><li>翻訳エンジンの優先順位で、Azure Translatorを使いたい順位に置きます。</li></ol><p>キーは、このPCの設定にだけ保存されます。</p><h2 id="うまくいかないとき" tabindex="-1">うまくいかないとき <a class="header-anchor" href="#うまくいかないとき" aria-label="Permalink to &quot;うまくいかないとき&quot;">​</a></h2><table tabindex="0"><thead><tr><th>状況</th><th>確認すること</th></tr></thead><tbody><tr><td>テストで、キーが正しくないと出る</td><td>キーの前後に空白が入っていないか。別のリソース(Translator以外)のキーではないか</td></tr><tr><td>テストで、リージョンのエラーが出る</td><td>「場所/地域」の文字をそのまま入れたか(<code>Japan East</code> ではなく <code>japaneast</code>)</td></tr><tr><td>しばらく使えていたのに、急に失敗する</td><td>月200万文字の枠を使い切っていないか。Azureポータルの、リソースの「メトリック」で確認できます</td></tr><tr><td>作った直後に失敗する</td><td>作ってから使えるようになるまで、数分かかることがあります</td></tr></tbody></table><p>Mutelinkの 設定 &gt; 翻訳 には、このPCのこのアプリが翻訳した文字数(今月・今日・直近30日)が出ます。同じキーをほかの場所でも使っているときは、その分は入りません。</p><h2 id="やめるとき" tabindex="-1">やめるとき <a class="header-anchor" href="#やめるとき" aria-label="Permalink to &quot;やめるとき&quot;">​</a></h2><p>Azureポータルで、作ったリソース(またはリソース グループごと)を削除します。Mutelinkの 設定 &gt; 翻訳 のキーの欄も、空にします。</p><p>登録条件や価格レベルの詳細は、Microsoftの<a href="https://azure.microsoft.com/ja-jp/pricing/purchase-options/azure-account" target="_blank" rel="noreferrer">Azureアカウントの説明</a>と<a href="https://learn.microsoft.com/ja-jp/azure/ai-services/translator/how-to/create-translator-resource" target="_blank" rel="noreferrer">Translatorリソースの作成手順</a>を確認してください。</p>',26)])])}const g=e(o,[["render",n]]);export{p as __pageData,g as default};
